const freezeMeeting=await apiCall({action:'create',company:'WMK',type:'eos_meeting',name:'Automatic snapshot L10',owner:'Lead',attendees:'Lead',conclusion:'Reviewed current sources',rating:8,date:engine.day(),requestId:engine.uid()});
await apiCall({action:'stage',id:freezeMeeting.id,status:'In progress',requestId:engine.uid()});
await apiCall({action:'stage',id:freezeMeeting.id,status:'Completed',requestId:engine.uid()});
const storedMeeting=JSON.parse(sql.prepare('SELECT payload FROM records WHERE id=?').get(freezeMeeting.id).payload),snapshotMetric=storedMeeting.reviewSnapshot.scorecards.find(r=>r.id===apiMetric.id);
check(snapshotMetric.actual===projection.records.find(r=>r.id===apiMetric.id).actual&&snapshotMetric.metricSource==='Posted revenue','Completed L10 saves derived metric value and source');
const readLinked=(await (await GET(new Request('https://erp.local/api/erp'))).json()).records.find(r=>r.id===apiMetric.id);check(readLinked.actual===snapshotMetric.actual&&readLinked.metricSource==='Posted revenue'&&readLinked.metricEvidence,'ERP API returns calculated linked actual and source note');
const beforeSnapshot=JSON.stringify(storedMeeting.reviewSnapshot);
await apiCall({action:'edit',id:apiMetric.id,fields:{targetValue:999999},requestId:engine.uid()});
check(JSON.stringify(JSON.parse(sql.prepare('SELECT payload FROM records WHERE id=?').get(freezeMeeting.id).payload).reviewSnapshot)===beforeSnapshot,'Later metric edits do not change closed meeting snapshot');

const dynamicMeeting=await apiCall({action:'create',company:'WMK',type:'eos_meeting',name:'Dynamic API L10',owner:'Lead',attendees:'Team',date:engine.day(),conclusion:'Reviewed',rating:8,requestId:engine.uid()});
await apiCall({action:'stage',id:dynamicMeeting.id,status:'In progress',requestId:engine.uid()});
const pauseId=engine.uid();await apiCall({action:'meeting_control',id:dynamicMeeting.id,command:'Pause',requestId:pauseId});await apiCall({action:'meeting_control',id:dynamicMeeting.id,command:'Pause',requestId:pauseId});
let dynamicSaved=(await (await GET(new Request('https://erp.local/api/erp'))).json()).records.find(r=>r.id===dynamicMeeting.id);check(dynamicSaved.l10Clock.paused&&dynamicSaved.version===2,'Pause persisted once through API');
await apiCall({action:'meeting_control',id:dynamicMeeting.id,command:'Resume',expectedVersion:dynamicSaved.version,requestId:engine.uid()});
await apiCall({action:'meeting_control',id:dynamicMeeting.id,command:'Next',expectedVersion:dynamicSaved.version,requestId:engine.uid()},false);
await apiCall({action:'meeting_control',id:dynamicMeeting.id,command:'Next',requestId:engine.uid()});
dynamicSaved=(await (await GET(new Request('https://erp.local/api/erp'))).json()).records.find(r=>r.id===dynamicMeeting.id);check(dynamicSaved.agendaStep==='Scorecard'&&dynamicSaved.l10Clock.elapsedByStep.Segue>=0,'Section and elapsed time read back');
await apiCall({action:'stage',id:dynamicMeeting.id,status:'Completed',requestId:engine.uid()});
await apiCall({action:'meeting_control',id:dynamicMeeting.id,command:'Resume',requestId:engine.uid()},false);
check((await (await GET(new Request('https://erp.local/api/erp'))).json()).records.find(r=>r.id===dynamicMeeting.id).reviewSnapshot.timer.completedAt,'Closed timer snapshot persists');

const directStartRequest={action:'start_l10',company:'Hagadol',owner:'Lead',attendees:'Team',requestId:engine.uid()};
const directStart=await apiCall(directStartRequest);await apiCall(directStartRequest);
let activeL10=(await (await GET(new Request('https://erp.local/api/erp'))).json()).records.find(r=>r.id===directStart.id);check(activeL10.status==='In progress'&&activeL10.l10Clock&&!activeL10.reviewSnapshot,'Direct start persists active meeting and clock');
const beforeEndCount=sql.prepare('SELECT COUNT(*) AS n FROM records').get().n;
await apiCall({action:'end_l10',id:directStart.id,expectedVersion:activeL10.version,todos:[{name:'Invalid action',owner:'Lead',due:''}],conclusion:'Decision',rating:8,actionsConfirmed:true,requestId:engine.uid()},false);
check(sql.prepare('SELECT COUNT(*) AS n FROM records').get().n===beforeEndCount,'Invalid ending creates no partial tasks');
await apiCall({action:'end_l10',id:directStart.id,expectedVersion:99,todos:[],conclusion:'Decision',rating:8,actionsConfirmed:true,noActions:true,requestId:engine.uid()},false);
const endRequest={action:'end_l10',id:directStart.id,expectedVersion:activeL10.version,todos:[{name:'Prepare client quotation',owner:'Sales',due:engine.day()},{name:'Confirm site access',owner:'Operations',due:engine.day()}],conclusion:'Deliver agreed actions',rating:9,actionsConfirmed:true,requestId:engine.uid()};
await apiCall(endRequest);await apiCall(endRequest);
const endRead=(await (await GET(new Request('https://erp.local/api/erp'))).json()).records;activeL10=endRead.find(r=>r.id===directStart.id);const outputs=endRead.filter(r=>r.type==='task'&&r.meetingId===directStart.id);
check(outputs.length===2&&outputs.every(r=>r.eos&&r.company==='Hagadol'&&r.owner&&r.due),'Atomic end produces two assigned EOS To dos exactly once');
check(activeL10.status==='Completed'&&activeL10.l10Clock.paused&&activeL10.reviewSnapshot.todos.filter(r=>r.meetingId===directStart.id).length===2,'Readback includes closed meeting and frozen action output');
await apiCall({...endRequest,requestId:engine.uid()},false);check(sql.prepare('SELECT COUNT(*) AS n FROM records').get().n===beforeEndCount+2,'Repeated ending cannot duplicate follow up actions');

